using Tarification.Domaine;

namespace Tarification.Application;

/// <summary>
/// Ce qu'un client doit payer, et le détail qui l'explique. Les remises et les frais de port
/// restent à zéro tant que les stories correspondantes ne sont pas livrées : mieux vaut un champ
/// visiblement vide qu'un champ absent qu'on oublierait de remplir.
/// </summary>
public sealed record Facture(Montant SommeDesArticles, Montant Remise, Montant FraisDePort)
{
    public Montant ATPayer => SommeDesArticles + FraisDePort;
}

/// <summary>
/// Cas d'usage : chiffrer un panier. Point d'entrée de la couche application, c'est lui que les
/// tests d'acceptance pilotent.
/// </summary>
public sealed class CalculDuPanier
{
    public Facture Chiffrer(Panier panier) => new(panier.SommeDesLignes(), Montant.Zero, Montant.Zero);
}

namespace Tarification.Domaine;

/// <summary>Un article et sa quantité, au prix unitaire du moment.</summary>
public sealed record LigneDePanier(string Reference, Quantite Quantite, Montant PrixUnitaire)
{
    public Montant SousTotal => PrixUnitaire.Multiplie(Quantite.Valeur);
}

namespace Tarification.Domaine;

/// <summary>
/// Une somme d'argent, en euros. Type-valeur : deux montants égaux sont interchangeables, et un
/// montant négatif n'existe pas dans ce domaine — un remboursement serait un autre concept.
/// </summary>
public readonly record struct Montant : IComparable<Montant>
{
    public decimal Euros { get; }

    private Montant(decimal euros) => Euros = euros;

    public static Montant De(decimal euros) =>
        euros < 0 ? throw new ArgumentOutOfRangeException(nameof(euros), euros, "Un montant ne peut pas être négatif.") : new Montant(euros);

    public static Montant Zero { get; } = new(0m);

    public static Montant operator +(Montant a, Montant b) => new(a.Euros + b.Euros);

    public Montant Multiplie(int facteur) =>
        facteur < 0 ? throw new ArgumentOutOfRangeException(nameof(facteur), facteur, "Un facteur négatif n'a pas de sens ici.") : new Montant(Euros * facteur);

    public int CompareTo(Montant autre) => Euros.CompareTo(autre.Euros);

    public override string ToString() => $"{Euros:0.00} €";
}

namespace Tarification.Domaine;

/// <summary>Les lignes retenues par un client. Un panier peut être vide : son total vaut zéro.</summary>
public sealed class Panier
{
    private readonly List<LigneDePanier> _lignes = [];

    public IReadOnlyList<LigneDePanier> Lignes => _lignes;

    public Panier Ajoute(LigneDePanier ligne)
    {
        _lignes.Add(ligne);
        return this;
    }

    public Montant SommeDesLignes() => _lignes.Aggregate(Montant.Zero, (total, l) => total + l.SousTotal);
}

namespace Tarification.Domaine;

/// <summary>Un nombre d'articles. Au moins un : une ligne de panier vide n'a pas lieu d'être.</summary>
public readonly record struct Quantite
{
    public int Valeur { get; }

    private Quantite(int valeur) => Valeur = valeur;

    public static Quantite De(int valeur) =>
        valeur < 1 ? throw new ArgumentOutOfRangeException(nameof(valeur), valeur, "Une quantité vaut au moins 1.") : new Quantite(valeur);

    public override string ToString() => Valeur.ToString();
}

using System.Globalization;
using Reqnroll;
using Tarification.Application;
using Tarification.Domaine;
using Xunit;

namespace Tarification.UnitTests;

[Binding]
public sealed class ChiffrageDuPanierSteps
{
    private Panier _panier = new();
    private Facture? _facture;

    [Given("un panier vide")]
    public void UnPanierVide() => _panier = new Panier();

    [Given(@"une ligne ""([^""]+)"" de (\d+) articles à (\d+(?:\.\d+)?) euros")]
    public void UneLigne(string reference, int quantite, string prix)
    {
        _panier.Ajoute(new LigneDePanier(
            reference, Quantite.De(quantite), Montant.De(decimal.Parse(prix, CultureInfo.InvariantCulture))));
    }

    [When("le client chiffre son panier")]
    public void ChiffrerLePanier() => _facture = new CalculDuPanier().Chiffrer(_panier);

    [Then(@"la somme des articles est de (\d+(?:\.\d+)?) euros")]
    public void VerifierLaSomme(string somme)
    {
        Assert.NotNull(_facture);
        Assert.Equal(Montant.De(decimal.Parse(somme, CultureInfo.InvariantCulture)), _facture.SommeDesArticles);
    }
}

using Tarification.Domaine;
using Xunit;

namespace Tarification.Tests;

/// <summary>
/// Validation des valeurs du domaine, en complément des scénarios BDD de l'US-1.
/// </summary>
public class CalculDuPanierTests
{
    [Fact]
    public void Une_quantite_nulle_ou_negative_n_existe_pas()
    {
        Assert.Throws<ArgumentOutOfRangeException>(() => Quantite.De(0));
        Assert.Throws<ArgumentOutOfRangeException>(() => Quantite.De(-2));
    }

    [Fact]
    public void Un_montant_negatif_n_existe_pas()
    {
        Assert.Throws<ArgumentOutOfRangeException>(() => Montant.De(-0.01m));
    }
}
